    "codeExample": "class BankAccount {\n    // PRIVATE: క్లాస్ లోపల మాత్రమే ఉండే అత్యంత రహస్యమైన డేటా\n    private double balance;\n    private String pin;\n    private int failedAttempts;\n\n    // Package-private (default): ఈ ప్యాకేజ్ లో వాళ్లు వాడుకోవచ్చు\n    static final int MAX_FAILED_ATTEMPTS = 3;\n\n    // PUBLIC: బయటవాళ్ళు డబ్బులు డిపాజిట్ చేయడానికి మనం ఇచ్చిన ఓపెన్ గేట్\n    public void deposit(double amount) {\n        if (amount > 0) {\n            balance += amount;\n            logTransaction(\"DEPOSIT\", amount);\n        } else {\n            System.out.println(\"  [వార్నింగ్] మైనస్ డబ్బులు వేయలేరు!\");\n        }\n    }\n\n    // PUBLIC: బ్యాలెన్స్ చదవడానికి (కానీ మార్చడానికి కాదు) ఒక గెట్టర్\n    public double getBalance() {\n        return balance;\n    }\n\n    // PRIVATE: మనం ఇంటర్నల్ గా లాగ్స్ రాసుకునే సిస్టమ్, బయట వాళ్ళకి ఇది కనపడదు\n    private void logTransaction(String type, double amount) {\n        System.out.printf(\"  [సీక్రెట్ లాగ్] %s: $%.2f | కొత్త బ్యాలెన్స్: $%.2f%n\",\n                type, amount, balance);\n    }\n\n    // PUBLIC: అకౌంట్ ఓపెన్ చేయడానికి కన్స్ట్రక్టర్\n    public BankAccount(double initialDeposit, String pin) {\n        if (initialDeposit >= 0) this.balance = initialDeposit;\n        this.pin = pin;\n        this.failedAttempts = 0;\n    }\n\n    // PUBLIC: పిన్ కరెక్ట్ కాదో చెక్ చేయడానికి\n    public boolean verifyPin(String inputPin) {\n        if (failedAttempts >= MAX_FAILED_ATTEMPTS) {\n            System.out.println(\"  [సెక్యూరిటీ] 3 సార్లు తప్పు కొట్టారు, అకౌంట్ లాక్ అయ్యింది!\");\n            return false;\n        }\n        if (pin.equals(inputPin)) {\n            failedAttempts = 0;\n            System.out.println(\"  పిన్ కరెక్ట్!\");\n            return true;\n        }\n        failedAttempts++;\n        System.out.printf(\"  [వార్నింగ్] తప్పు పిన్. ఇంక %d ఛాన్సులు ఉన్నాయి%n\",\n                MAX_FAILED_ATTEMPTS - failedAttempts);\n        return false;\n    }\n\n    // PUBLIC: డైరెక్ట్ గా ప్రింట్ చేస్తే అర్థమయ్యేలా\n    @Override\n    public String toString() {\n        return String.format(\"BankAccount{బ్యాలెన్స్=$%.2f}\", balance);\n    }\n}\n\npublic class Main {\n    public static void main(String[] args) {\n        System.out.println(\"=== బ్యాంక్ అకౌంట్ సెక్యూరిటీ డెమో ===\");\n        BankAccount account = new BankAccount(1000.0, \"9876\");\n\n        // పబ్లిక్ మెథడ్స్ తో పర్ఫెక్ట్ గా పనిచేస్తుంది\n        account.deposit(500.0);\n        account.deposit(250.0);\n        System.out.println(\"ప్రస్తుత బ్యాలెన్స్: $\" + account.getBalance());\n\n        System.out.println(\"\n=== పిన్ బ్లాక్ అయ్యే సిస్టమ్ ===\");\n        account.verifyPin(\"1234\");  // తప్పు పిన్\n        account.verifyPin(\"4321\");  // తప్పు పిన్\n        account.verifyPin(\"9876\");  // కరెక్ట్ పిన్\n\n        System.out.println(\"\n=== ప్రైవేట్ సెక్యూరిటీ ఎలా పనిచేస్తుందంటే ===\");\n        // కింద ఉన్న రెండు లైన్స్ లో కామెంట్స్ తీస్తే ఎర్రర్స్ వస్తాయి చూడండి:\n        // account.balance = 999999;    // ఎర్రర్: ప్రైవేట్ ఫీల్డ్ కి డైరెక్ట్ యాక్సెస్ లేదు\n        // account.logTransaction(...); // ఎర్రర్: ప్రైవేట్ మెథడ్\n        System.out.println(\"ప్రైవేట్ ఉన్న వాటిని మనం ఇక్కడి నుంచి పిలవలేము!\");\n        System.out.println(\"ఫైనల్ అకౌంట్: \" + account);\n    }\n}",
    "output": "=== బ్యాంక్ అకౌంట్ సెక్యూరిటీ డెమో ===\n  [సీక్రెట్ లాగ్] DEPOSIT: $500.00 | కొత్త బ్యాలెన్స్: $1500.00\n  [సీక్రెట్ లాగ్] DEPOSIT: $250.00 | కొత్త బ్యాలెన్స్: $1750.00\nప్రస్తుత బ్యాలెన్స్: $1750.0\n\n=== పిన్ బ్లాక్ అయ్యే సిస్టమ్ ===\n  [వార్నింగ్] తప్పు పిన్. ఇంక 2 ఛాన్సులు ఉన్నాయి\n  [వార్నింగ్] తప్పు పిన్. ఇంక 1 ఛాన్సులు ఉన్నాయి\n  పిన్ కరెక్ట్!\n\n=== ప్రైవేట్ సెక్యూరిటీ ఎలా పనిచేస్తుందంటే ===\nప్రైవేట్ ఉన్న వాటిని మనం ఇక్కడి నుంచి పిలవలేము!\nఫైనల్ అకౌంట్: BankAccount{బ్యాలెన్స్=$1750.00}",
