    "practicalExample": "// ప్యాకేజ్ లోపల మాత్రమే ఉండే క్లాస్ (utility)\nclass PasswordHasher {\n    // ఈ ప్యాకేజ్ లో ఉన్నవాళ్లు మాత్రమే పాస్వర్డ్స్ హాష్ చేయగలరు\n    static String hash(String password) {\n        // ఇది జస్ట్ డమ్మీ కోడ్ (రియల్ ప్రొడక్షన్ కాదు!)\n        int hash = password.hashCode();\n        return \"HASH_\" + Math.abs(hash);\n    }\n}\n\n// అందరికీ అందుబాటులో ఉండే పబ్లిక్ క్లాస్\npublic class PracticalApplication {\n    public static void main(String[] args) {\n        System.out.println(\"=== Access Modifier డెమో ===\");\n        String raw = \"mySecretPass123\";\n        String hashed = PasswordHasher.hash(raw); // ఒకే ప్యాకేజ్ కాబట్టి యాక్సెస్ ఉంది\n        System.out.println(\"రా పాస్వర్డ్  : \" + raw);\n        System.out.println(\"హాష్ అయ్యాక   : \" + hashed);\n    }\n}",
