    "challenge": "// Coding Challenge:\n// ఒక SecureVault క్లాస్ క్రియేట్ చేయండి:\n// 1. private String secretCode (ఎవరూ చదవలేరు).\n// 2. private int accessAttempts కౌంటర్.\n// 3. public boolean attemptAccess(String code) రాసి కరెక్ట్ కోడ్ అయితేనే true ఇవ్వాలి, మాక్స్ 3 టైమ్స్.\n// 4. 3 టైమ్స్ అయితే లాక్ అయ్యేలా isLocked() రాయాలి.\n\nclass SecureVault {\n    private final String secretCode;\n    private int accessAttempts = 0;\n    private static final int MAX_ATTEMPTS = 3;\n\n    public SecureVault(String secretCode) {\n        this.secretCode = secretCode;\n    }\n\n    public boolean attemptAccess(String code) {\n        if (isLocked()) {\n            System.out.println(\"  వాల్ట్ లాక్ అయ్యింది! అడ్మిన్ కి కాల్ చేయండి.\");\n            return false;\n        }\n        accessAttempts++;\n        if (secretCode.equals(code)) {\n            System.out.println(\"  యాక్సెస్ గ్రాంటెడ్!\");\n            return true;\n        }\n        System.out.println(\"  పాస్వర్డ్ తప్పు. అటెంప్ట్ \" + accessAttempts + \"/\" + MAX_ATTEMPTS);\n        return false;\n    }\n\n    public boolean isLocked() { return accessAttempts >= MAX_ATTEMPTS; }\n}\n\npublic class Challenge {\n    public static void main(String[] args) {\n        SecureVault vault = new SecureVault(\"JAVA2026\");\n        vault.attemptAccess(\"WRONG1\");\n        vault.attemptAccess(\"WRONG2\");\n        vault.attemptAccess(\"JAVA2026\"); // 3వ సారి కరెక్ట్ కొట్టాం\n    }\n}",
