    "codeExample": "class Employee {\n    // సెక్యూరిటీ కోసం ప్రైవేట్ ఫీల్డ్స్\n    private final String employeeId; // ఫైనల్ - దీనికి సెట్టర్ ఉండదు\n    private String name;\n    private String email;\n    private double salary;\n    private boolean active;\n    private int[] projectIds;        // అరే - డేంజర్, కాపీస్ ఇవ్వాలి\n\n    public Employee(String name, String email, double salary, int[] projectIds) {\n        this.employeeId = \"EMP-\" + System.currentTimeMillis() % 100000;\n        setName(name); // డైరెక్ట్ వాల్యూ వేయకుండా సెట్టర్ పిలుస్తున్నాం (వాలిడేషన్ కోసం)\n        setEmail(email);\n        setSalary(salary);\n        // అరే కాబట్టి జిరాక్స్ కాపీ చేసుకుంటున్నాం\n        this.projectIds = projectIds != null ? projectIds.clone() : new int[0];\n        this.active = true;\n    }\n\n    // GETTERS (రీడ్ ఓన్లీ)\n    public String getEmployeeId()  { return employeeId; }\n    public String getName()        { return name; }\n    public String getEmail()       { return email; }\n    public double getSalary()      { return salary; }\n    public boolean isActive()      { return active; } // is అని ఉండాలి!\n\n    // Defensive copy - గెట్టర్ లో కూడా జిరాక్స్ కాపీనే ఇస్తున్నాం\n    public int[] getProjectIds()   { return projectIds.clone(); }\n\n    // Computed property — ఫార్ములాతో క్రియేట్ అయ్యేది\n    public String getDisplayTitle() {\n        return (active ? \"[ACTIVE] \" : \"[INACTIVE] \") + name + \" <\" + email + \">\";\n    }\n\n    // SETTERS (వాలిడేషన్ తో)\n    public void setName(String name) {\n        if (name == null || name.isBlank())\n            throw new IllegalArgumentException(\"పేరు ఖాళీగా ఉండకూడదు.\");\n        this.name = name.trim();\n    }\n\n    public void setEmail(String email) {\n        // రెగ్యులర్ ఎక్స్ప్రెషన్ తో ఈమెయిల్ ఫార్మాట్ కరెక్ట్ ఉందో లేదో చెక్ చేస్తున్నాం\n        if (email == null || !email.matches(\"^[\\w.-]+@[\\w.-]+\\.\\w{2,}$\"))\n            throw new IllegalArgumentException(\"ఈమెయిల్ ఫార్మాట్ తప్పు: \" + email);\n        this.email = email.toLowerCase().trim();\n    }\n\n    public void setSalary(double salary) {\n        if (salary < 15000)\n            throw new IllegalArgumentException(\"మరీ ఇంత తక్కువ శాలరీ ఏంటయ్యా: \" + salary);\n        this.salary = salary;\n    }\n\n    public void setActive(boolean active)      { this.active = active; }\n    public void setProjectIds(int[] projectIds) {\n        this.projectIds = projectIds != null ? projectIds.clone() : new int[0];\n    }\n\n    @Override\n    public String toString() {\n        return String.format(\"[%s] %-18s | శాలరీ: $%,9.2f | యాక్టివ్: %b\",\n                employeeId, name, salary, active);\n    }\n}\n\npublic class Main {\n    public static void main(String[] args) {\n        System.out.println(\"=== 1. ఎంప్లాయీ ఆబ్జెక్ట్ క్రియేషన్ ===\");\n        Employee emp = new Employee(\"Ravi Kumar\", \"ravi.kumar@company.com\",\n                85000.0, new int[]{101, 205, 312});\n        System.out.println(emp);\n        System.out.println(\"డిస్ప్లే టైటిల్ : \" + emp.getDisplayTitle());\n\n        System.out.println(\"\n=== 2. సెట్టర్ తో అప్డేట్ ===\");\n        emp.setSalary(92000.0);\n        System.out.println(\"జీతం పెరిగాక  : \" + emp);\n\n        System.out.println(\"\n=== 3. వాలిడేషన్స్ ఎలా ఆపుతున్నాయో చూద్దాం ===\");\n        try {\n            emp.setSalary(-500.0); // మైనస్ జీతం!\n        } catch (IllegalArgumentException e) {\n            System.out.println(\"శాలరీ ఎర్రర్  : \" + e.getMessage());\n        }\n\n        try {\n            emp.setEmail(\"not-an-email\"); // తప్పు ఈమెయిల్!\n        } catch (IllegalArgumentException e) {\n            System.out.println(\"ఈమెయిల్ ఎర్రర్: \" + e.getMessage());\n        }\n\n        System.out.println(\"\n=== 4. Defensive Copy పవర్ చూద్దాం ===\");\n        int[] returnedIds = emp.getProjectIds();\n        returnedIds[0] = 9999; // బయటవాడు అరే ని కరప్ట్ చేస్తున్నాడు\n        System.out.println(\"బయట మార్చిన వాల్యూ  : \" + returnedIds[0]);\n        System.out.println(\"మన ఆబ్జెక్ట్ లో వాల్యూ : \" + emp.getProjectIds()[0]); // మనది సేఫ్! 101 ఏ ఉంటుంది\n\n        System.out.println(\"\n=== 5. ఫార్ములా ప్రాపర్టీ (Computed) ===\");\n        emp.setActive(false);\n        System.out.println(\"ఇన్-యాక్టివ్ టైటిల్ : \" + emp.getDisplayTitle());\n    }\n}",
