    "challenge": "// Coding Challenge:\n// ఒక BankAccount క్లాస్ ని క్రియేట్ చేయండి:\n// 1. private double balance (దీనికి సెట్టర్ రాయొద్దు, కేవలం deposit, withdraw లే దీన్ని మార్చాలి).\n// 2. private String accountHolder (సెట్టర్ వద్దు, డిఫాల్ట్ గా final పెట్టండి).\n// 3. getBalance() ఎప్పుడూ 2 డెసిమల్స్ కే రౌండ్ చేసి పంపాలి.\n// 4. deposit(amount): పాజిటివ్ అయితేనే బ్యాలెన్స్ లో యాడ్ చేయాలి.\n// 5. withdraw(amount): అమౌంట్ > 0 మరియు బ్యాలెన్స్ ఉంటేనే తీయాలి.\n\nclass BankAccount {\n    private final String accountHolder;\n    private double balance;\n\n    public BankAccount(String holder, double initialBalance) {\n        if (holder == null || holder.isBlank()) throw new IllegalArgumentException(\"పేరు కచ్చితంగా ఉండాలి\");\n        this.accountHolder = holder.trim();\n        this.balance = Math.max(0, initialBalance);\n    }\n\n    public String getAccountHolder() { return accountHolder; }\n\n    public double getBalance() {\n        return Math.round(balance * 100.0) / 100.0;\n    }\n\n    public void deposit(double amount) {\n        if (amount <= 0) throw new IllegalArgumentException(\"డిపాజిట్ మైనస్ లో ఉండదు!\");\n        balance += amount;\n    }\n\n    public void withdraw(double amount) {\n        if (amount <= 0 || amount > balance)\n            throw new IllegalArgumentException(\"బ్యాలెన్స్ లేదు బ్రో: \" + amount);\n        balance -= amount;\n    }\n}\n\npublic class Challenge {\n    public static void main(String[] args) {\n        BankAccount acc = new BankAccount(\"Priya\", 1000.0);\n        acc.deposit(500.0);\n        acc.withdraw(200.0);\n        System.out.println(acc.getAccountHolder() + \" అకౌంట్ బ్యాలెన్స్: $\" + acc.getBalance());\n    }\n}",
