    "practicalExample": "// ఇది ఒక కంపెనీ ఆడిట్ లాగ్ సిస్టమ్ (ఇది కచ్చితంగా ఇమ్మ్యూటబుల్ ఉండాలి, లేకపోతే రికార్డ్స్ ఎవరైనా మార్చేయగలరు!)\nfinal class AuditEntry {\n    private final String userId;\n    private final String action;\n    private final long timestamp;\n\n    public AuditEntry(String userId, String action) {\n        if (userId == null || action == null) throw new IllegalArgumentException(\"డేటా కరెక్ట్ గా లేదు.\");\n        this.userId    = userId;\n        this.action    = action;\n        this.timestamp = System.currentTimeMillis();\n    }\n\n    public String getUserId()   { return userId; }\n    public String getAction()   { return action; }\n    public long getTimestamp()  { return timestamp; }\n\n    @Override\n    public String toString() {\n        return String.format(\"AuditEntry{యూజర్='%s', పని='%s', టైమ్=%d}\", userId, action, timestamp);\n    }\n}\n\npublic class PracticalApplication {\n    public static void main(String[] args) {\n        AuditEntry e1 = new AuditEntry(\"USR-001\", \"LOGIN\");\n        AuditEntry e2 = new AuditEntry(\"USR-001\", \"TRANSFER_FUNDS\");\n        AuditEntry e3 = new AuditEntry(\"USR-002\", \"CHANGE_PASSWORD\");\n\n        System.out.println(\"=== సీక్రెట్ ఆడిట్ లాగ్ (ఎవరూ మార్చలేనిది) ===\");\n        System.out.println(e1);\n        System.out.println(e2);\n        System.out.println(e3);\n    }\n}",
