    "challenge": "// Coding Challenge:\n// ఒక ఇమ్మ్యూటబుల్ Version క్లాస్ రాయండి (ఉదాహరణకి ఆండ్రాయిడ్ 14.1.2 లాగా):\n// ఫీల్డ్స్: final int major, minor, patch.\n// రూల్: అన్నీ >= 0 ఉండాలి.\n// మెథడ్స్: isNewerThan(Version other), toString() ఇవి 14.1.2 లాగా రిటర్న్ చేయాలి.\n\nfinal class Version {\n    private final int major;\n    private final int minor;\n    private final int patch;\n\n    public Version(int major, int minor, int patch) {\n        if (major < 0 || minor < 0 || patch < 0) throw new IllegalArgumentException(\"వర్షన్ మైనస్ లో ఉండదు\");\n        this.major = major;\n        this.minor = minor;\n        this.patch = patch;\n    }\n\n    public boolean isNewerThan(Version other) {\n        if (this.major != other.major) return this.major > other.major;\n        if (this.minor != other.minor) return this.minor > other.minor;\n        return this.patch > other.patch;\n    }\n\n    @Override\n    public String toString() {\n        return major + \".\" + minor + \".\" + patch;\n    }\n}\n\npublic class Challenge {\n    public static void main(String[] args) {\n        Version v1 = new Version(2, 1, 0);\n        Version v2 = new Version(2, 0, 5);\n        System.out.println(v1 + \" ఇది కొత్తదా \" + v2 + \" కన్నా ?: \" + v1.isNewerThan(v2));\n    }\n}",
